<?php if($view==='auth'): $action=['login.php'=>'login','register.php'=>'register','forgot-password.php'=>'forgot','reset-password.php'=>'reset'][$currentPage]; ?>
<div class="login-area py-90"><div class="container"><div class="col-lg-5 mx-auto"><div class="login-form"><div class="login-header"><h3><?= h($pageTitle) ?></h3></div><form method="post" class="store-form"><?= csrf_field() ?><input type="hidden" name="action" value="<?= $action ?>"><?php if($action==='register'): ?><label for="name">Full name</label><input name="name" id="name" required maxlength="190" autocomplete="name" value="<?= h($_POST['name']??'') ?>"><?php endif; ?><?php if($action!=='reset'): ?><label for="email">Email</label><input type="email" id="email" name="email" required maxlength="190" autocomplete="email" value="<?= h($_POST['email']??'') ?>"><?php else: ?><input type="hidden" name="token" value="<?= h($_GET['token']??$_POST['token']??'') ?>"><?php endif; ?><?php if($action!=='forgot'): ?><label for="password">Password<?= $action!=='login'?' (at least 12 characters)':'' ?></label><input type="password" id="password" name="password" required <?= $action!=='login'?'minlength="12"':'' ?> autocomplete="<?= $action==='login'?'current-password':'new-password' ?>"><?php endif; ?><button class="theme-btn w-100"><?= h($pageTitle) ?></button></form><div class="login-footer mt-4"><a href="<?= url('login.php') ?>">Login</a> · <a href="<?= url('register.php') ?>">Register</a> · <a href="<?= url('forgot-password.php') ?>">Forgot password?</a></div></div></div></div></div>
<?php else: $u=require_user(); ?><div class="user-area bg pt-100 pb-80"><div class="container"><div class="row"><div class="col-lg-3"><?php require __DIR__.'/../../overall/sidenav.php'; ?></div><div class="col-lg-9"><div class="user-wrapper"><div class="user-card"><h4 class="user-card-title"><?= h($pageTitle) ?></h4>
<?php if($currentPage==='user-dashboard.php'): $summary=row('SELECT COUNT(*) count,COALESCE(SUM(CASE WHEN status NOT IN ("cancelled","refunded") THEN total ELSE 0 END),0) spend FROM orders WHERE user_id=?',[$u['id']]); ?><div class="row"><div class="col-md-6"><div class="dashboard-widget color-1"><div class="dashboard-widget-info"><h2><?= $summary['count'] ?></h2><span>Orders</span></div></div></div><div class="col-md-6"><div class="dashboard-widget color-2"><div class="dashboard-widget-info"><h2><?= h(money($summary['spend'])) ?></h2><span>Order value</span></div></div></div></div><p>Welcome, <?= h($u['name']) ?>.</p><a class="theme-btn mt-3" href="<?= url('order-list.php') ?>">View your orders</a>
<?php elseif($currentPage==='user-profile.php'): ?><form method="post" class="store-form"><?= csrf_field() ?><input type="hidden" name="action" value="profile"><label for="name">Name</label><input name="name" id="name" required value="<?= h($u['name']) ?>"><label>Email</label><p class="mb-3"><?= h($u['email']) ?></p><label for="phone">Phone</label><input name="phone" id="phone" value="<?= h($u['phone']) ?>"><button class="theme-btn">Save profile</button></form>
<?php elseif($currentPage==='user-setting.php'): ?><form method="post" class="store-form"><?= csrf_field() ?><input type="hidden" name="action" value="password"><label for="current_password">Current password</label><input id="current_password" type="password" name="current_password" autocomplete="current-password" required><label for="password">New password (at least 12 characters)</label><input id="password" type="password" name="password" autocomplete="new-password" minlength="12" required><button class="theme-btn">Change password</button></form>
<?php elseif($currentPage==='order-list.php'): $page=max(1,(int)($_GET['page']??1));$orders=rows('SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC LIMIT 20 OFFSET '.(($page-1)*20),[$u['id']]); ?><div class="table-responsive"><table class="table"><thead><tr><th>Order</th><th>Date</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><a href="<?= url('order-detail.php?id='.$o['id']) ?>">#<?= $o['id'] ?></a></td><td><?= h($o['created_at']) ?></td><td><?= h($o['status']) ?></td><td><?= h($o['currency'].' '.number_format($o['total'],2)) ?></td></tr><?php endforeach; ?></tbody></table><?php if(!$orders): ?><p>You have no orders yet.</p><?php endif; ?></div><?php if($page>1): ?><a href="?page=<?= $page-1 ?>">Previous</a><?php endif; ?> <?php if(count($orders)===20): ?><a href="?page=<?= $page+1 ?>">Next</a><?php endif; ?>
<?php elseif($currentPage==='address-list.php'): ?><a class="theme-btn mb-4" href="<?= url('add-address.php') ?>">Add address</a><?php foreach(rows('SELECT * FROM addresses WHERE user_id=?',[$u['id']]) as $a): ?><div class="border rounded p-3 mb-3"><h5><?= h($a['name']) ?></h5><p><?= h($a['address'].' — '.$a['city'].' '.$a['country']) ?></p><p><?= h($a['phone']) ?></p><a href="<?= url('add-address.php?id='.$a['id']) ?>">Edit</a><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="address_delete"><input type="hidden" name="id" value="<?= $a['id'] ?>"><button class="btn">Delete address</button></form></div><?php endforeach; ?>
<?php elseif($currentPage==='add-address.php'): $a=row('SELECT * FROM addresses WHERE id=? AND user_id=?',[(int)($_GET['id']??0),$u['id']]); ?><form method="post" class="store-form"><?= csrf_field() ?><input type="hidden" name="action" value="address"><input type="hidden" name="id" value="<?= $a['id']??0 ?>"><?php foreach(['name','phone','address','city','country'] as $k): ?><label for="<?= $k ?>"><?= ucfirst($k) ?></label><input id="<?= $k ?>" name="<?= $k ?>" required value="<?= h($_POST[$k]??$a[$k]??$u[$k]??($k==='country'?setting('country','Kenya'):'')) ?>"><?php endforeach; ?><button class="theme-btn">Save address</button></form><?php endif; ?>
